#!/usr/bin/env python3
"""Production results dispatcher with real sequencer and stubbed display/restart."""
from pathlib import Path
import json,subprocess
r=Path(__file__).resolve().parents[1];o=r/'out/parity-audit/results-integration';o.mkdir(parents=True,exist_ok=True)
s=(r/'src/game.c').read_text();a=s.index('static u8 game_results_update(void)');b=s.index('\nbool game_update',a)
prefix='#include <assert.h>\n#include "arcade_results.h"\n#include "arcade_player.h"\n#include "arcade_life.h"\n#define FLOW_GAME_OVER 3\n#define FALSE 0\n#define TRUE 1\n#define BG_A 0\ntypedef struct {u32 score;u8 flow;} Player;\nstatic struct {Player players[2];u8 numPlayers;} g_game;\nstatic ArcadeResults g_results;\nstatic u8 g_resultsActive,g_resultsDisplay,g_resultsPlayers,g_attract;\nstatic u8 clock_value,busy,life_owned[2];\nstatic ArcadeLife player_life[2];static ArcadePlayerAnimation player_animation[2];\nstatic unsigned starts,restarts,awards[2],animates,events,flushes;\nu8 entity_arcade_clock(void){return clock_value;}\nvoid entity_arcade_clock_advance(void){clock_value++;}\nu8 arcade_results_display_pending(void){if(busy){busy--;return 1;}return 0;}\nvoid VDP_setEnable(u8 v){(void)v;}\nvoid DMA_flushQueue(void){flushes++;}\nvoid arcade_results_display_begin(void){starts++;busy=2;}\nvoid VDP_setHorizontalScroll(u8 plane,s16 scroll){(void)plane;assert(scroll==0);}\nvoid arcade_life_animation_step(ArcadeLife*p){(void)p;animates++;}\nvoid arcade_player_animation_step(ArcadePlayerAnimation*p){(void)p;animates++;}\nvoid arcade_results_display_event(const ArcadeResultsEvent*e){(void)e;events++;}\nvoid check_extra_life(Player*p){awards[p-g_game.players]++;}\nvoid game_course_restart(void){restarts++;g_resultsActive=g_resultsDisplay=g_resultsPlayers=0;}\n'
suffix='\nint main(void){unsigned phase,mask,attract,total=0;\nfor(attract=0;attract<2;attract++)for(mask=0;mask<4;mask++)for(phase=0;phase<256;phase++){\n unsigned ticks=0;u8 previous;\n g_results=(ArcadeResults){0,0,0,3};g_resultsActive=1;g_resultsDisplay=g_resultsPlayers=0;\n g_attract=attract;clock_value=phase;busy=0;g_game.numPlayers=2;\n g_game.players[0]=(Player){9900,(mask&1)?0:FLOW_GAME_OVER};\n g_game.players[1]=(Player){8700,(mask&2)?0:FLOW_GAME_OVER};\n starts=restarts=flushes=events=animates=awards[0]=awards[1]=0;\n life_owned[0]=1;life_owned[1]=0;\n while(g_resultsActive){previous=clock_value;entity_arcade_clock_advance();game_results_update();\n  assert(clock_value==(u8)(previous+1));assert(++ticks<500);\n }\n assert(starts==1 && restarts==1 && flushes==1);\n assert(g_game.players[0].score==9900+(!attract && (mask&1)?40000:0));\n assert(g_game.players[1].score==8700+(!attract && (mask&2)?40000:0));\n assert(awards[0]==(!attract && (mask&1)?1:0));assert(awards[1]==(!attract && (mask&2)?1:0));\n assert(g_results.course==4 && events>0);if(mask)assert(animates>0);total++;\n}assert(total==2048);return 0;}\n'
(o/'test.c').write_text(prefix+s[a:b]+suffix)
subprocess.run(['cc','-std=c99','-Wall','-Wextra','-Werror','-I'+str(r/'inc'),str(o/'test.c'),str(r/'src/arcade_results.c'),'-o',str(o/'test')],check=True)
subprocess.run([str(o/'test')],check=True)
report={'cases':2048,'scope':'Production game_results_update with real sequencer; stub display, animation, extra-life and restart effects. Verifies clock handoff, busy waits, awards/attract suppression and one restart request. Full game_course_restart/VDP behavior remains unverified.'}
(o/'results.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps(report,indent=2))
